draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // eyes
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2, 10, 0, 2 * Math.PI);
  ctx.fill();

  // eyebrows
  ctx.beginPath();
  ctx.moveTo(W/2 - 60, H/2 - 20);
  ctx.lineTo(W/2 - 40, H/2 - 20 + 10 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 40, H/2 - 20);
  ctx.lineTo(W/2 + 60, H/2 - 20 + 10 * Math.sin(t));
  ctx.stroke();

  // mouth
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2 + 20);
  ctx.lineTo(W/2 + 30, H/2 + 20);
  ctx.stroke();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 70);
  ctx.lineTo(W/2 - 30, H/2 + 90);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 70);
  ctx.lineTo(W/2 + 30, H/2 + 90);
  ctx.stroke();

  // hands
  ctx.beginPath();
  ctx.arc(W/2 - 30, H/2 + 90, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 30, H/2 + 90, 10, 0, 2 * Math.PI);
  ctx.fill();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 - 20, H/2 + 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 + 20, H/2 + 150);
  ctx.stroke();

  // other person
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 20);
  ctx.lineTo(W/2 + 100, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 30);
  ctx.lineTo(W/2 + 70, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 30);
  ctx.lineTo(W/2 + 130, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 50);
  ctx.lineTo(W/2 + 100, H/2 + 100);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2 + 120, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2 + 120, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 70);
  ctx.lineTo(W/2 + 70, H/2 + 90);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 70);
  ctx.lineTo(W/2 + 130, H/2 + 90);
  ctx.stroke();

  ctx.restore();
}
